/**
 * The four states. `NOT_OBSERVABLE` is in the SAME enum as the rest, not a separate error channel, so
 * a caller that switches on this type is forced to write the branch that says "I cannot see this".
 * Collapsing it into `NOT_STARTED` is the bug this whole module exists to prevent.
 */
export type QuestStatus = 'COMPLETE' | 'IN_PROGRESS' | 'NOT_STARTED' | 'NOT_OBSERVABLE';

/** A named stage value the content actually compares this quest's progress varp against. */
export interface QuestMilestone {
    /** constant name without the caret, e.g. `prince_saved`. */
    readonly name: string;
    readonly value: number;
}

/** A varp declared in the quest's own config dir that is NOT its progress varp. */
export interface QuestAuxVarp {
    readonly name: string;
    readonly transmitted: boolean;
    /** how many loc/op gates in obstacles.json test this varp. */
    readonly gates: number;
}

export interface QuestDef {
    /** questlist component name without the `questlist:` prefix. The stable key. */
    readonly key: string;
    /** display name, from questlist.if `text=`. */
    readonly name: string;
    /** questlist:<key> component id — the IF_SETCOLOUR target that carries this quest's tri-state. */
    readonly component: number;
    /**
     * Progress varp NAME, or null when the journal computes progress in a proc instead. This is the
     * key `BotProfile.quests` is indexed by, which is why the NAME is always emitted even when the id
     * is not.
     */
    readonly varp: string | null;
    /**
     * Whether `varp` names a VARP or a VARBIT. RuneScript writes `%name` for both and nothing in the
     * script text tells them apart — `%horrorquest` is bits 0..10 of the varp `deephorror`.
     */
    readonly kind: 'varp' | 'varbit' | null;
    /** does the server ever push this (for a varbit: its BASE varp) to a client? */
    readonly transmitted: boolean;
    /**
     * ⛔ THE ONLY ID A READER MAY PASS TO getVarp(). `-1` when it does not transmit — in which case
     * the real id is deliberately ABSENT from this file, because a non-transmitted varp reads 0
     * forever and 0 is a plausible value. For a varbit this is the BASE varp's id.
     */
    readonly readVarpId: number;
    /** varbit extraction: `(raw >>> bitShift) & bitMask`. `bitMask === -1` means "the whole varp". */
    readonly bitShift: number;
    readonly bitMask: number;
    /**
     * ⛔ This quest's journal row is coloured from a DIFFERENT variable on one branch of
     * update_questlist, so the colour does not identify what it describes and cannot bound `varp`.
     * The reader refuses the colour channel for these — see the row's `note`.
     */
    readonly journalAmbiguous: boolean;
    /** `^<name>_complete` — the value at which the journal turns the quest green. */
    readonly complete: number;
    readonly completeName: string;
    /** quest points awarded, from [proc,count_questpoints]. Every quest in the table awards >= 1;
     *  they sum to 145, which is what a fully-completed account's `qp` varp reads. */
    readonly questPoints: number;
    /** stage constants the content compares this varp against, ascending. */
    readonly milestones: readonly QuestMilestone[];
    /** other varps this quest's config dir declares — sub-state that gates locs but is not progress. */
    readonly aux: readonly QuestAuxVarp[];
    /** how many loc/op gates in obstacles.json test the PROGRESS varp. */
    readonly gates: number;
    /** anything surprising about this row. Read it before trusting the numbers. */
    readonly note: string | null;
}

